<template>
  <v-container class="mt-4">
    <v-overlay :value="overlay">
      <v-progress-circular
          color="primary"
          indeterminate
          size="50"
      ></v-progress-circular>
    </v-overlay>
    <v-navigation-drawer
      app
      class="primary darken-1 white--text"
      clipped
      permanent
      right
      style="z-index: 3;"
    >
      <v-list class="white--text">
        <v-list-item>
          <v-btn class="primary" dark @click="$router.push('/resource/view/student/' + queries.practitioner)">
            <v-icon light left>mdi-eye</v-icon>
            <span>View Student</span>
          </v-btn>
        </v-list-item>
        <v-list-item>
          <v-btn :disabled="!canFinanceReview" class="success" dark @click="approvalDialog = true">
            <v-icon light left>mdi-check-decagram</v-icon>
            <span>Finance Director Review</span>
          </v-btn>
        </v-list-item>
        <v-list-item>
          <v-btn :disabled="!canTaalimReview" class="success" dark @click="approvalDialog = true">
            <v-icon light left>mdi-check-decagram</v-icon>
            <span>Taalim Director Review</span>
          </v-btn>
        </v-list-item>
        <v-list-item>
          <v-btn :disabled="!hasTask('can-edit-registration')" class="success" dark @click="$router.push('/custom/edit_registration?path=/itsf&id=' + queries.role + '&practitioner=' + queries.practitioner)">
            <v-icon light left>mdi-eye</v-icon>
            <span>Edit</span>
          </v-btn>
        </v-list-item>
        <v-list-item>
          <v-btn :disabled='!canPrintId' class="success" dark @click="printid">
            <v-icon light left>mdi-eye</v-icon>
            <span>Print ID</span>
          </v-btn>
        </v-list-item>
        <v-list-item>
          <v-btn class="success" dark @click="$router.push('/questionnaire/itsf-school-fees-payments/feespayments?practitionerrole=' + queries.role)">
            <v-icon light left>mdi-contactless-payment-circle-outline</v-icon>
            <span>Pay Fees</span>
          </v-btn>
        </v-list-item>
      </v-list>
    </v-navigation-drawer>
    <v-dialog
      v-model="approvalDialog"
      persistent
      max-width="500px"
      transition="dialog-transition"
    >
      <v-card>
        <v-toolbar color="primary" class="darken-1 white--text text-uppercase font-weight-bold" dark>
          Approve/Reject Registration
          <v-spacer></v-spacer>
          <v-btn icon color="white" @click="approvalDialog = false">
            <v-icon>mdi-close</v-icon>
          </v-btn>
        </v-toolbar>
        <v-card-text>
          <v-select
            :items="statuses"
            v-model="status"
            label="Status"
            outlined
            dense
            class="ma-2"
            hide-details
            clearable
          ></v-select>
        </v-card-text>
        <v-card-actions>
          <v-spacer></v-spacer>
          <v-btn color="success" :disabled="!status" @click="save">Save</v-btn>
        </v-card-actions>
      </v-card>
    </v-dialog>
    <fhir-page-view :id="queries.role" page="practitionerrole" @templates-loaded="registrationPageLoaded" :showDrawer="false" />
    <v-row>
      <v-col v-for="(payment, index) in payments" :key="index" cols="12">
        <v-btn color="success" @click="$router.push('/custom/edit_fees?path=/itsf&id=' + payment + '&practitioner=' + queries.practitioner + '&role=' + queries.role)">Edit Below Fee</v-btn>
        <fhir-page-view v-if="rows[payment]" :id="payment" page="feespayments" :showDrawer="false" @templates-loaded="feesTemplateLoaded(index)" />
      </v-col>
      <v-col cols="12">
        <fhir-page-view v-if="financeReviewPage" :id="financeReviewId" page="finance-review" :showDrawer="false" @templates-loaded="taalimReviewPage = true" />
      </v-col>
      <v-col cols="12">
        <fhir-page-view v-if="taalimReviewPage" :id="taalimReviewId" page="taalim-review" :showDrawer="false" />
      </v-col>
    </v-row>
  </v-container>
</template>

<script>
export default {
  props: ["queries"],
  data: function() {
    return {
      financeReview: {},
      taalimReview: {},
      taalimReviewId: "",
      financeReviewId: "",
      taalimReviewPage: false,
      financeReviewPage: false,
      statusText: "",
      status: "",
      regStatus: "",
      statuses: [{
        text: "Approve",
        value: "approved"
      }, {
        text: "Reject",
        value: "rejected"
      }, {
        text: "Pending",
        value: "pending"
      }],
      displaySecond: false,
      payments: [],
      approvalDialog: false,
      rows: {
        fake: false
      },
      overlay: false,
      familyHeadInactive: true,
      registrationDisplayed: false
    }
  },
  computed: {
    role() {
      let role = this.$store.state.user.obj.resource.extension.find((ext) => {
        return ext.url === 'http://ihris.org/fhir/StructureDefinition/ihris-assign-role'
      }).valueReference.reference
      return role.split("/")[1]
    },
    canApprove() {
      if(!this.familyHeadInactive && this.regStatus != 'approved') {
        return true
      }
      return false
    },
    canFinanceReview() {
      if(!this.familyHeadInactive && this.financeReview.code != 'approved' && this.role === 'itsf-admin-finance-role') {
        return true
      }
      return false
    },
    canTaalimReview() {
      if(!this.familyHeadInactive && this.financeReview.code == 'approved' && this.taalimReview.code !== 'approved' && this.role === 'itsf-taalim-role') {
        return true
      }
      return false
    },
    canPrintId() {
      if(this.financeReview.code == 'approved' && this.taalimReview.code === 'approved' && this.role === 'itsf-id-card-manager') {
        return true
      }
      return false
    }
  },
  methods: {
    registrationPageLoaded() {
      if(!this.rows[this.payments[0]]) {
        this.rows[this.payments[0]] = true
      }
      this.registrationDisplayed = true
    },
    feesTemplateLoaded(index) {
      if(this.payments.length == 1) {
        this.financeReviewPage = true
      } else if(this.payments.length === index+1) {
        this.financeReviewPage = true
      } else {
        this.rows[this.payments[index+1]] = true
      }
    },
    getPayment() {
      return new Promise((resolve) => {
        fetch("/fhir/Basic?_elements=id&registrationfeespayment=PractitionerRole/" + this.queries.role).then((response) => {
          response.json().then((response) => {
            if(response.entry) {
              for(let entry of response.entry) {
                this.payments.push(entry.resource.id)
                this.$set(this.rows, entry.resource.id, false)
              }
              if(this.registrationDisplayed) {
                this.rows[this.payments[0]] = true
              }
            }
            resolve()
          }).catch(() => {
            resolve()
          })
        }).catch(() => {
          resolve()
        })
      })
    },
    getReviewStatuses() {
      return new Promise((resolve) => {
        fetch("/fhir/Basic?registrationreference=PractitionerRole/" + this.queries.role + "&_profile=http://ihris.org/fhir/StructureDefinition/taalim-registration-review-profile,http://ihris.org/fhir/StructureDefinition/finance-registration-review-profile").then((response) => {
          response.json().then((response) => {
            let finance = response.entry.find((entry) => {
              return entry.resource.meta.profile.includes("http://ihris.org/fhir/StructureDefinition/finance-registration-review-profile")
            })
            let taalim = response.entry.find((entry) => {
              return entry.resource.meta.profile.includes("http://ihris.org/fhir/StructureDefinition/taalim-registration-review-profile")
            })
            if(finance) {
              this.financeReviewId = finance.resource.id
              this.financeReview = finance.resource.extension.find((ext) => {
                return ext.url === "http://ihris.org/fhir/StructureDefinition/registration-status"
              })?.valueCoding
            }
            if(taalim) {
              this.taalimReviewId = taalim.resource.id
              this.taalimReview = taalim.resource.extension.find((ext) => {
                return ext.url === "http://ihris.org/fhir/StructureDefinition/registration-status"
              })?.valueCoding
            }
            if(!this.familyHeadInactive && this.financeReview.code != 'approved') {
              this.status = this.financeReview.code
            } else if(this.financeReview.code === 'pending') {
              this.statusText = "Waiting Finance Director Approval"
            }
            if(!this.familyHeadInactive && this.financeReview.code == 'approved' && this.taalimReview.code !== 'approved') {
              this.status = this.taalimReview.code
            } else if(this.taalimReview.code === 'pending') {
              this.statusText = "Waiting Finance Director Approval"
            }
            this.regStatus = this.status
            resolve()
          }).catch(() => {
            resolve()
          })
        }).catch(() => {
          resolve()
        })
      })
    },
    getFamilyHead() {
      return new Promise((resolve) => {
        let url = "/fhir/Basic?_profile=http://ihris.org/fhir/StructureDefinition/itsf-family-head-profile&practitioner=Practitioner/" + this.queries.practitioner + "&familymemberactive=yes"
        fetch(url).then((response) => {
          response.json().then((response) => {
            if(response.entry) {
              let head = response.entry[0].resource.extension.find((ext) => {
                return ext.url === "http://ihris.org/fhir/StructureDefinition/family-head"
              })?.valueReference?.reference
              if(head) {
                let body = {
                  resource: "PractitionerRole",
                  params: {
                    practitioner: "Practitioner/" + head.split("/")[1]
                  }
                }
                fetch("/site/student/getLatestResourceById/", {
                  method: "POST",
                  headers: {
                    "Content-Type": "application/json",
                  },
                  redirect: "manual",
                  body: JSON.stringify(body),
                }).then((response) => {
                  if(response.ok) {
                    response.json().then((response) => {
                      if(response.entry.length) {
                        let regStatus = response.entry[0].resource.extension.find((ext) => {
                          return ext.url === "http://ihris.org/fhir/StructureDefinition/registration-status"
                        })?.valueCoding?.code
                        if(regStatus !== 'approved') {
                          this.familyHeadInactive = true
                        } else {
                          this.familyHeadInactive = false
                        }
                      }
                    })
                  } else {
                    this.familyHeadInactive = true
                  }
                })
              }
            } else {
              this.familyHeadInactive = false
            }
            resolve()
          }).catch(() => {
            resolve()
          })
        }).catch(() => {
          resolve()
        })
      })
    },
    save() {
      let body = {
        status: this.status,
        practitionerrole: this.queries.role,
        practitioner: this.queries.practitioner,
        role: this.role
      }
      fetch("/site/student/registration_approval", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        redirect: "manual",
        body: JSON.stringify(body),
      }).then((response) => {
        if(response.ok) {
          this.$store.commit("setMessage", {
            type: "success",
            text: "Registration Processed Successfully",
          });
          this.$router.push('/resource/view/student/' + this.queries.practitioner)
        } else {
          this.$store.commit("setMessage", {
            type: "error",
            text: "Failed to process registration",
          });
        }
      })
    },
    printid() {
      this.overlay = true
      fetch("/site/student/printId/" + this.queries.practitioner).then((response) =>{
        response.blob().then((blob) => {
          fetch("/fhir/Practitioner/" + this.queries.practitioner).then((response) => {
            response.json().then((pract) => {
              this.overlay = false
              let fullname = ""
              let name = pract.name.find((nm) => {
                nm.use === "official"
              })
              if(!name && pract.name && pract.name.length > 0) {
                name = pract.name[0]
              }
              if(name) {
                if(name.given) {
                  if(fullname) {
                    fullname += " "
                  }
                  fullname += name.given.join(" ")
                }
                if(name.family) {
                  if(fullname) {
                    fullname += " "
                  }
                  fullname += name.family
                }
              }
              let link = document.createElement("a");
              link.href = window.URL.createObjectURL(blob);
              link.download = `${fullname}.pdf`;
              link.click();
            }).catch(() => {
              this.overlay = false
            })
          }).catch(() => {
              this.overlay = false
            })
        }).catch(() => {
          this.overlay = false
        })
      }).catch(() => {
        this.overlay = false
      })
    },
    hasTask(task) {
      return this.$store.state.user.obj.permissions && this.$store.state.user.obj.permissions.special && this.$store.state.user.obj.permissions.special.special && this.$store.state.user.obj.permissions.special.special.id && this.$store.state.user.obj.permissions.special.special.id[task]
    }
  },
  created() {
    this.overlay = true
    Promise.all([this.getPayment(), this.getFamilyHead(), this.getReviewStatuses()]).then(() => {
      this.overlay = false
    })
  },
  components: {
    "fhir-page-view": () => import("@/views/fhir-page-view")
  },
}
</script>